1	/**
2	 * @module MommaPageLayout
3	 *
4	 * Layout decorativo de página com identidade visual Momma.
5	 * Inclui faixa de toldo na parte superior, folhas animadas no fundo
6	 * e brilhos ambientes sutis.
7	 */
8	
9	import React from 'react';
10	import { Leaf, Sun, Moon, Sparkles } from 'lucide-react'; // Added Sparkles here just in case, though unrelated to layout background directly
11	import { cn } from '@/shared/lib/utils';
12	import { useTheme } from 'next-themes';
13	import { Button } from '@/shared/ui/button';
14	
15	interface MommaPageLayoutProps {
16	  children: React.ReactNode;
17	  className?: string;
18	  showAwning?: boolean;
19	  pageTitle?: string; // Optional: for pages that want a consistent title header
20	}
21	
22	/**
23	 * Layout de página com elementos decorativos da marca Momma.
24	 * Renderiza faixa de toldo, folhas animadas e brilhos ambientes como fundo.
25	 *
26	 * @param children - Conteúdo principal da página.
27	 * @param className - Classes CSS adicionais para o container de conteúdo.
28	 * @param showAwning - Se exibe a faixa de toldo no topo (padrão: `true`).
29	 * @param pageTitle - Título opcional da página (reservado para uso futuro).
30	 */
31	export function MommaPageLayout({
32	  children,
33	  className,
34	  showAwning = true,
35	  pageTitle,
36	}: MommaPageLayoutProps) {
37	  const { theme, setTheme } = useTheme();
38	
39	  return (
40	    <div className="flex flex-col min-h-[100dvh] bg-white dark:bg-[#0A0A0A] overflow-x-hidden relative font-sans transition-colors duration-300">
41	      {/* Store Awning Stripe Effect (Top Border) */}
42	      {showAwning && (
43	        <div className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50 pointer-events-none" />
44	      )}
45	
46	      {/* Animated Plant Background Elements */}
47	      <div className="fixed inset-0 pointer-events-none overflow-hidden z-0">
48	        <div
49	          className="absolute top-[-5%] right-[-10%] w-[300px] h-[300px] opacity-[0.03] dark:opacity-[0.05] animate-pulse"
50	          style={{ animationDuration: '10s' }}
51	        >
52	          <Leaf className="w-full h-full text-[#57715B] rotate-12" />
53	        </div>
54	        <div
55	          className="absolute bottom-[-10%] left-[-15%] w-[400px] h-[400px] opacity-[0.03] dark:opacity-[0.05] animate-pulse delay-1000"
56	          style={{ animationDuration: '12s' }}
57	        >
58	          <Leaf className="w-full h-full text-[#57715B] -rotate-45" />
59	        </div>
60	
61	        {/* Soft Ambient Glows */}
62	        <div className="absolute top-[20%] left-[10%] w-[200px] h-[200px] bg-[#57715B]/5 rounded-full blur-[80px]" />
63	        <div className="absolute bottom-[30%] right-[10%] w-[250px] h-[250px] bg-[#C5A065]/5 rounded-full blur-[80px]" />
64	      </div>
65	
66	      {/* Main Content */}
67	      <div className={cn('relative z-10 flex-1 flex flex-col', className)}>
68	        {children}
69	      </div>
70	
71	      {/* Floating Theme Toggle (Optional - usually in header, but keeping layout distinct) */}
72	      {/* This layout focuses on background. Headers are usually page specific or DashboardLayout specific. 
73	                 Using this effectively means wrapping current page content. */}
74	    </div>
75	  );
76	}
