1	import { useState, useMemo } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import {
4	  Calculator, Plus, Search, CheckCircle2, Clock, Archive,
5	  ChevronDown, Trash2, Workflow,
6	} from 'lucide-react';
7	import { cn } from '@/shared/lib/utils';
8	import { Badge } from '@/shared/ui/badge';
9	import { Button } from '@/shared/ui/button';
10	import { Input } from '@/shared/ui/input';
11	import {
12	  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter,
13	} from '@/shared/ui/dialog';
14	import {
15	  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
16	  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
17	} from '@/shared/ui/alert-dialog';
18	import {
19	  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
20	} from '@/shared/ui/select';
21	import {
22	  DropdownMenu, DropdownMenuContent, DropdownMenuItem,
23	  DropdownMenuSeparator, DropdownMenuTrigger,
24	} from '@/shared/ui/dropdown-menu';
25	import { useCmvFichas, type CmvStatus } from '@/features/financeiro/model/useCmvFichas';
26	
27	const STATUS_CONFIG: Record<CmvStatus, { label: string; icon: typeof Clock; className: string }> = {
28	  rascunho: {
29	    label: 'Rascunho',
30	    icon: Clock,
31	    className: 'bg-zinc-100 text-zinc-700 dark:bg-zinc-800 dark:text-zinc-300',
32	  },
33	  aprovada: {
34	    label: 'Aprovada',
35	    icon: CheckCircle2,
36	    className: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400',
37	  },
38	  obsoleta: {
39	    label: 'Obsoleta',
40	    icon: Archive,
41	    className: 'bg-zinc-100 text-zinc-500 dark:bg-zinc-800 dark:text-zinc-500',
42	  },
43	};
44	
45	const fmt = (n: number | null | undefined): string => {
46	  if (typeof n !== 'number') return 'R$ 0,00';
47	  return n.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
48	};
49	
50	export default function CmvPage() {
51	  const navigate = useNavigate();
52	  const {
53	    cmvList,
54	    availableFichas,
55	    isLoading,
56	    createCmv,
57	    updateCmvStatus,
58	    deleteCmv,
59	  } = useCmvFichas();
60	
61	  const [busca, setBusca] = useState('');
62	  const [statusFiltro, setStatusFiltro] = useState<CmvStatus | 'todos'>('todos');
63	  const [isNewDialogOpen, setIsNewDialogOpen] = useState(false);
64	  const [newCmvNome, setNewCmvNome] = useState('');
65	  const [selectedFichaId, setSelectedFichaId] = useState<string>('');
66	  const [deleteId, setDeleteId] = useState<number | null>(null);
67	
68	  const filteredCmvs = useMemo(() => {
69	    return cmvList.filter((cmv) => {
70	      const matchBusca =
71	        cmv.nome.toLowerCase().includes(busca.toLowerCase()) ||
72	        (cmv.ficha_nome ?? '').toLowerCase().includes(busca.toLowerCase());
73	      const matchStatus = statusFiltro === 'todos' || cmv.status === statusFiltro;
74	      return matchBusca && matchStatus;
75	    });
76	  }, [cmvList, busca, statusFiltro]);
77	
78	  const handleCreate = async () => {
79	    if (!selectedFichaId || !newCmvNome.trim()) return;
80	    const fichaId = Number(selectedFichaId);
81	    if (!Number.isFinite(fichaId)) return;
82	    const result = await createCmv.mutateAsync({ ficha_tecnica_id: fichaId, nome: newCmvNome.trim() });
83	    setIsNewDialogOpen(false);
84	    if (result?.id) {
85	      navigate(`/financeiro/cmv/configurador?focus=${result.id}`);
86	    }
87	  };
88	
89	  const handleDelete = async () => {
90	    if (!deleteId) return;
91	    await deleteCmv.mutateAsync(deleteId);
92	    setDeleteId(null);
93	  };
94	
95	  const handleFichaSelect = (fichaId: string) => {
96	    setSelectedFichaId(fichaId);
97	    if (!newCmvNome) {
98	      const ficha = availableFichas.find((f) => f.id === Number(fichaId));
99	      if (ficha) setNewCmvNome(`CMV — ${ficha.nome}`);
100	    }
101	  };
102	
103	  return (
104	    <div className="min-h-screen bg-white dark:bg-[#0A0A0A] relative overflow-hidden flex flex-col">
105	      {/* Awning stripe */}
106	      <div className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50" />
107	
108	      {/* Ambient glows */}
109	      <div className="fixed top-[10%] left-[10%] w-[500px] h-[500px] bg-[#57715B]/5 blur-[80px] rounded-full pointer-events-none" />
110	      <div className="fixed bottom-[10%] right-[10%] w-[400px] h-[400px] bg-[#C5A065]/5 blur-[80px] rounded-full pointer-events-none" />
111	
112	      {/* Watermark */}
113	      <div className="fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 opacity-[0.03] pointer-events-none animate-pulse" style={{ animationDuration: '12s' }}>
114	        <Calculator className="w-[400px] h-[400px] text-[#57715B]" />
115	      </div>
116	
117	      <div className="relative z-10 w-full max-w-[1600px] mx-auto px-4 sm:px-6 py-8 mt-2">
118	        {/* Header */}
119	        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8">
120	          <div className="flex items-center gap-3">
121	            <div className="rounded-2xl bg-[#57715B]/10 p-3">
122	              <Calculator className="h-6 w-6 text-[#57715B]" />
123	            </div>
124	            <div>
125	              <h1 className="text-2xl md:text-4xl font-bold tracking-tight text-[#2D362E] dark:text-[#E6DCCF]">
126	                CMV
127	              </h1>
128	              <p className="text-xs uppercase tracking-widest text-muted-foreground">
129	                Custo de Mercadoria Vendida
130	              </p>
131	            </div>
132	          </div>
133	
134	          <Button
135	            className="bg-[#57715B] hover:bg-[#465b49] text-white shadow-lg shadow-[#57715B]/20"
136	            onClick={() => {
137	              setNewCmvNome('');
138	              setSelectedFichaId('');
139	              setIsNewDialogOpen(true);
140	            }}
141	          >
142	            <Plus className="mr-1.5 h-4 w-4" />
143	            Novo CMV
144	          </Button>
145	        </div>
146	
147	        {/* Filtros */}
148	        <div className="flex flex-wrap gap-2 mb-6">
149	          <div className="relative flex-1 min-w-[180px] max-w-xs">
150	            <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
151	            <Input
152	              className="pl-8 h-9 text-sm"
153	              placeholder="Buscar CMV ou ficha..."
154	              value={busca}
155	              onChange={(e) => setBusca(e.target.value)}
156	            />
157	          </div>
158	          <Select
159	            value={statusFiltro}
160	            onValueChange={(v) => setStatusFiltro(v as CmvStatus | 'todos')}
161	          >
162	            <SelectTrigger className="h-9 w-[160px] text-sm">
163	              <SelectValue placeholder="Status" />
164	            </SelectTrigger>
165	            <SelectContent>
166	              <SelectItem value="todos">Todos os status</SelectItem>
167	              <SelectItem value="rascunho">Rascunho</SelectItem>
168	              <SelectItem value="aprovada">Aprovada</SelectItem>
169	              <SelectItem value="obsoleta">Obsoleta</SelectItem>
170	            </SelectContent>
171	          </Select>
172	        </div>
173	
174	        {/* Content */}
175	        {isLoading ? (
176	          <div className="flex items-center justify-center py-20 text-muted-foreground text-sm">
177	            Carregando CMVs...
178	          </div>
179	        ) : filteredCmvs.length === 0 ? (
180	          <div className="flex flex-col items-center justify-center gap-3 py-20 text-center">
181	            <div className="rounded-2xl bg-[#57715B]/10 p-4">
182	              <Calculator className="h-10 w-10 text-[#57715B]" />
183	            </div>
184	            <p className="text-sm text-muted-foreground">
185	              {cmvList.length === 0
186	                ? 'Nenhum CMV cadastrado. Crie o primeiro!'
187	                : 'Nenhum CMV corresponde aos filtros.'}
188	            </p>
189	            {cmvList.length === 0 && (
190	              <Button
191	                size="sm"
192	                variant="outline"
193	                onClick={() => { setNewCmvNome(''); setSelectedFichaId(''); setIsNewDialogOpen(true); }}
194	              >
195	                <Plus className="mr-1.5 h-4 w-4" />
196	                Criar primeiro CMV
197	              </Button>
198	            )}
199	          </div>
200	        ) : (
201	          <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-4 lg:gap-6">
202	            {filteredCmvs.map((cmv) => {
203	              const st = STATUS_CONFIG[cmv.status];
204	              const Icon = st.icon;
205	              const rendimento = cmv.ficha_rendimento_quantidade ?? 1;
206	              const custoFichaTotal = cmv.ficha_custo_calculado ?? 0;
207	              const unitarioFicha = rendimento > 0 ? custoFichaTotal / rendimento : 0;
208	              const custoTotal = cmv.custo_calculado ?? 0;
209	              const extras = Math.max(0, custoTotal - unitarioFicha);
210	
211	              return (
212	                <div
213	                  key={cmv.id}
214	                  className="group relative rounded-2xl border border-white/30 dark:border-white/10 bg-white/60 dark:bg-zinc-900/40 backdrop-blur-xl shadow-sm hover:shadow-xl hover:-translate-y-1 p-5 transition-all duration-300 overflow-hidden"
215	                >
216	                  <div className="absolute inset-0 bg-gradient-to-br from-white/40 via-transparent to-black/5 pointer-events-none" />
217	                  <div className="relative z-10">
218	                    <div className="flex items-start justify-between gap-3 mb-3">
219	                      <div className="flex-1 min-w-0">
220	                        <p className="font-semibold text-base text-foreground truncate">{cmv.nome}</p>
221	                        {cmv.ficha_nome && (
222	                          <p className="text-xs text-muted-foreground truncate mt-0.5 flex items-center gap-1">
223	                            <Workflow className="h-3 w-3 shrink-0" />
224	                            {cmv.ficha_nome}
225	                          </p>
226	                        )}
227	                      </div>
228	
229	                      <DropdownMenu>
230	                        <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
231	                          <Button
232	                            variant="ghost"
233	                            size="icon"
234	                            className="h-7 w-7 opacity-0 group-hover:opacity-100 transition-opacity"
235	                          >
236	                            <ChevronDown className="h-4 w-4" />
237	                          </Button>
238	                        </DropdownMenuTrigger>
239	                        <DropdownMenuContent align="end">
240	                          <DropdownMenuItem
241	                            onClick={() => navigate(`/financeiro/cmv/configurador?focus=${cmv.id}`)}
242	                          >
243	                            <Workflow className="mr-2 h-4 w-4 text-[#57715B]" />
244	                            Abrir no Construtor
245	                          </DropdownMenuItem>
246	                          {cmv.status !== 'aprovada' && (
247	                            <DropdownMenuItem
248	                              onClick={() => updateCmvStatus.mutate({ id: cmv.id, status: 'aprovada' })}
249	                            >
250	                              <CheckCircle2 className="mr-2 h-4 w-4 text-emerald-500" />
251	                              Aprovar
252	                            </DropdownMenuItem>
253	                          )}
254	                          {cmv.status !== 'obsoleta' && (
255	                            <DropdownMenuItem
256	                              onClick={() => updateCmvStatus.mutate({ id: cmv.id, status: 'obsoleta' })}
257	                            >
258	                              <Archive className="mr-2 h-4 w-4" />
259	                              Marcar obsoleta
260	                            </DropdownMenuItem>
261	                          )}
262	                          <DropdownMenuSeparator />
263	                          <DropdownMenuItem
264	                            className="text-destructive"
265	                            onClick={() => setDeleteId(cmv.id)}
266	                          >
267	                            <Trash2 className="mr-2 h-4 w-4" />
268	                            Excluir
269	                          </DropdownMenuItem>
270	                        </DropdownMenuContent>
271	                      </DropdownMenu>
272	                    </div>
273	
274	                    <span
275	                      className={cn(
276	                        'inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-[10px] uppercase tracking-wider font-bold',
277	                        st.className,
278	                      )}
279	                    >
280	                      <Icon className="h-3 w-3" />
281	                      {st.label}
282	                    </span>
283	
284	                    <div className="mt-4 pt-3 border-t border-[#57715B]/10">
285	                      <div className="flex items-end justify-between">
286	                        <div>
287	                          <p className="text-[10px] text-muted-foreground uppercase tracking-wider mb-0.5">
288	                            Custo total
289	                          </p>
290	                          <p className="text-xl font-bold text-emerald-600 dark:text-emerald-400 tabular-nums">
291	                            {fmt(custoTotal)}
292	                          </p>
293	                        </div>
294	                        <div className="text-right space-y-0.5">
295	                          <p className="text-[10px] text-muted-foreground">
296	                            Produção:{' '}
297	                            <span className="font-semibold text-foreground tabular-nums">
298	                              {fmt(unitarioFicha)}
299	                            </span>
300	                          </p>
301	                          <p className="text-[10px] text-muted-foreground">
302	                            Extras:{' '}
303	                            <span className="font-semibold text-foreground tabular-nums">
304	                              {fmt(extras)}
305	                            </span>
306	                          </p>
307	                        </div>
308	                      </div>
309	                    </div>
310	                  </div>
311	                </div>
312	              );
313	            })}
314	          </div>
315	        )}
316	      </div>
317	
318	      {/* Dialog Novo CMV */}
319	      <Dialog open={isNewDialogOpen} onOpenChange={setIsNewDialogOpen}>
320	        <DialogContent className="max-w-md">
321	          <DialogHeader>
322	            <DialogTitle>Novo CMV</DialogTitle>
323	          </DialogHeader>
324	          <div className="space-y-4 py-2">
325	            <div className="space-y-2">
326	              <p className="text-sm font-medium">Ficha Técnica Base *</p>
327	              {availableFichas.length === 0 ? (
328	                <div className="rounded-lg border border-amber-200 dark:border-amber-800 bg-amber-50 dark:bg-amber-900/20 p-3 text-sm text-amber-700 dark:text-amber-400">
329	                  Todas as fichas aprovadas já possuem CMV cadastrado.
330	                </div>
331	              ) : (
332	                <Select value={selectedFichaId} onValueChange={handleFichaSelect}>
333	                  <SelectTrigger>
334	                    <SelectValue placeholder="Selecione a ficha aprovada..." />
335	                  </SelectTrigger>
336	                  <SelectContent>
337	                    {availableFichas.map((f) => (
338	                      <SelectItem key={f.id} value={String(f.id)}>
339	                        {f.nome} — {f.rendimento_quantidade} {f.rendimento_unidade}
340	                      </SelectItem>
341	                    ))}
342	                  </SelectContent>
343	                </Select>
344	              )}
345	            </div>
346	
347	            <div className="space-y-2">
348	              <p className="text-sm font-medium">Nome do CMV *</p>
349	              <Input
350	                placeholder="Ex: CMV — Bolo de Chocolate"
351	                value={newCmvNome}
352	                onChange={(e) => setNewCmvNome(e.target.value)}
353	              />
354	            </div>
355	          </div>
356	          <DialogFooter>
357	            <Button variant="outline" onClick={() => setIsNewDialogOpen(false)}>
358	              Cancelar
359	            </Button>
360	            <Button
361	              className="bg-[#57715B] hover:bg-[#465b49] text-white"
362	              onClick={handleCreate}
363	              disabled={
364	                !selectedFichaId ||
365	                !newCmvNome.trim() ||
366	                availableFichas.length === 0 ||
367	                createCmv.isPending
368	              }
369	            >
370	              {createCmv.isPending ? 'Salvando...' : 'Salvar e Abrir Construtor'}
371	            </Button>
372	          </DialogFooter>
373	        </DialogContent>
374	      </Dialog>
375	
376	      {/* Alert delete */}
377	      <AlertDialog open={!!deleteId} onOpenChange={(o) => !o && setDeleteId(null)}>
378	        <AlertDialogContent>
379	          <AlertDialogHeader>
380	            <AlertDialogTitle>Excluir CMV?</AlertDialogTitle>
381	            <AlertDialogDescription>
382	              Esta ação é irreversível. Todos os itens de custo extras e posições do canvas serão removidos.
383	            </AlertDialogDescription>
384	          </AlertDialogHeader>
385	          <AlertDialogFooter>
386	            <AlertDialogCancel>Cancelar</AlertDialogCancel>
387	            <AlertDialogAction
388	              onClick={handleDelete}
389	              className="bg-destructive text-destructive-foreground"
390	            >
391	              Excluir
392	            </AlertDialogAction>
393	          </AlertDialogFooter>
394	        </AlertDialogContent>
395	      </AlertDialog>
396	    </div>
397	  );
398	}
