494	      .eq('id', selectedItemData.id);
495	
496	    if (error) {
497	      toast.error(`Erro ao excluir: ${error.message}`);
498	    } else {
499	      toast.success('Item removido!');
500	      setSelectedItemData(null);
501	      await refetch();
502	      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
503	    }
504	    setIsDeleting(false);
505	  }, [selectedItemData, refetch, queryClient]);
506	
507	  // -------------------------------------------------------------------------
508	  // Add item
509	  // -------------------------------------------------------------------------
