                          </DropdownMenuItem>
                          {cmv.status !== 'aprovada' && (
                            <DropdownMenuItem onClick={() => updateCmvStatus.mutate({ id: cmv.id, status: 'aprovada' })}>
                              <CheckCircle2 className="mr-2 h-4 w-4 text-emerald-500" />
                              Aprovar
                            </DropdownMenuItem>
                          )}
                          {cmv.status !== 'obsoleta' && (
                            <DropdownMenuItem onClick={() => updateCmvStatus.mutate({ id: cmv.id, status: 'obsoleta' })}>
                              <Archive className="mr-2 h-4 w-4" />
