                        <div>
                          <p className="text-[10px] text-muted-foreground uppercase tracking-wider mb-0.5">Custo total</p>
                          <p className="text-xl font-bold text-emerald-600 dark:text-emerald-400 tabular-nums">{fmt(custoTotal)}</p>
                        </div>
                        <div className="text-right space-y-0.5">
                          <p className="text-[10px] text-muted-foreground">Produção: <span className="font-semibold text-foreground tabular-nums">{fmt(unitarioFicha)}</span></p>
                          <p className="text-[10px] text-muted-foreground">Extras: <span className="font-semibold text-foreground tabular-nums">{fmt(extras)}</span></p>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

