            <div className="space-y-2">
              <p className="text-sm font-medium">Nome do CMV *</p>
              <Input placeholder="Ex: CMV — Bolo de Chocolate" value={newCmvNome} onChange={(e) => setNewCmvNome(e.target.value)} />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsNewDialogOpen(false)}>Cancelar</Button>
            <Button
              className="bg-[#57715B] hover:bg-[#465b49] text-white"
