            >
              {createCmv.isPending ? 'Salvando...' : 'Salvar e Abrir Construtor'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Alert delete */}
      <AlertDialog open={!!deleteId} onOpenChange={(o) => !o && setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Excluir CMV?</AlertDialogTitle>
