import { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Calculator, Plus, Search, CheckCircle2, Clock, Archive,
  ChevronDown, Trash2, Workflow,
} from 'lucide-react';
import { cn } from '@/shared/lib/utils';
import { Badge } from '@/shared/ui/badge';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter,
} from '@/shared/ui/dialog';
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from '@/shared/ui/alert-dialog';
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from '@/shared/ui/select';
import {
  DropdownMenu, DropdownMenuContent, DropdownMenuItem,
  DropdownMenuSeparator, DropdownMenuTrigger,
} from '@/shared/ui/dropdown-menu';
import { useCmvFichas, type CmvStatus } from '@/features/financeiro/model/useCmvFichas';
import { MommaPageLayout } from "@/components/layout/MommaPageLayout";

const STATUS_CONFIG: Record<CmvStatus, { label: string; icon: typeof Clock; className: string }> = {
  rascunho: {
    label: 'Rascunho',
    icon: Clock,
    className: 'bg-zinc-100 text-zinc-700 dark:bg-zinc-800 dark:text-zinc-300',
  },
  aprovada: {
    label: 'Aprovada',
    icon: CheckCircle2,
    className: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400',
  },
  obsoleta: {
    label: 'Obsoleta',
    icon: Archive,
    className: 'bg-zinc-100 text-zinc-500 dark:bg-zinc-800 dark:text-zinc-500',
  },
};

const fmt = (n: number | null | undefined): string => {
  if (typeof n !== 'number') return 'R$ 0,00';
  return n.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
};

export default function CmvPage() {
  const navigate = useNavigate();
  const {
    cmvList,
    availableFichas,
    isLoading,
    createCmv,
    updateCmvStatus,
    deleteCmv,
  } = useCmvFichas();

  const [busca, setBusca] = useState('');
  const [statusFiltro, setStatusFiltro] = useState<CmvStatus | 'todos'>('todos');
  const [isNewDialogOpen, setIsNewDialogOpen] = useState(false);
  const [newCmvNome, setNewCmvNome] = useState('');
  const [selectedFichaId, setSelectedFichaId] = useState<string>('');
  const [deleteId, setDeleteId] = useState<number | null>(null);

  const filteredCmvs = useMemo(() => {
    return cmvList.filter((cmv) => {
      const matchBusca =
        cmv.nome.toLowerCase().includes(busca.toLowerCase()) ||
        (cmv.ficha_nome ?? '').toLowerCase().includes(busca.toLowerCase());
      const matchStatus = statusFiltro === 'todos' || cmv.status === statusFiltro;
      return matchBusca && matchStatus;
    });
  }, [cmvList, busca, statusFiltro]);

  const handleCreate = async () => {
    if (!selectedFichaId || !newCmvNome.trim()) return;
    const fichaId = Number(selectedFichaId);
    if (!Number.isFinite(fichaId)) return;
    const result = await createCmv.mutateAsync({ ficha_tecnica_id: fichaId, nome: newCmvNome.trim() });
    setIsNewDialogOpen(false);
    if (result?.id) {
      navigate(`/financeiro/cmv/configurador?focus=${result.id}`);
    }
  };

  const handleDelete = async () => {
    if (!deleteId) return;
    await deleteCmv.mutateAsync(deleteId);
    setDeleteId(null);
  };

  const handleFichaSelect = (fichaId: string) => {
    setSelectedFichaId(fichaId);
    if (!newCmvNome) {
      const ficha = availableFichas.find((f) => f.id === Number(fichaId));
      if (ficha) setNewCmvNome(`CMV — ${ficha.nome}`);
    }
  };

  return (
    <MommaPageLayout>
      <div className="relative z-10 w-full max-w-[1600px] mx-auto px-4 sm:px-6 py-8 mt-2">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8">
          <div className="flex items-center gap-3">
            <div className="rounded-2xl bg-[#57715B]/10 p-3">
              <Calculator className="h-6 w-6 text-[#57715B]" />
            </div>
            <div>
              <h1 className="text-2xl md:text-4xl font-bold tracking-tight text-[#2D362E] dark:text-[#E6DCCF]">
                CMV
              </h1>
              <p className="text-xs uppercase tracking-widest text-muted-foreground">
                Custo de Mercadoria Vendida
              </p>
            </div>
          </div>

          <Button
            className="bg-[#57715B] hover:bg-[#465b49] text-white shadow-lg shadow-[#57715B]/20"
            onClick={() => {
              setNewCmvNome('');
              setSelectedFichaId('');
              setIsNewDialogOpen(true);
            }}
          >
            <Plus className="mr-1.5 h-4 w-4" />
            Novo CMV
          </Button>
        </div>

        {/* Filtros */}
        <div className="flex flex-wrap gap-2 mb-6">
          <div className="relative flex-1 min-w-[180px] max-w-xs">
            <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input
              className="pl-8 h-9 text-sm"
              placeholder="Buscar CMV ou ficha..."
              value={busca}
              onChange={(e) => setBusca(e.target.value)}
            />
          </div>
          <Select
            value={statusFiltro}
            onValueChange={(v) => setStatusFiltro(v as CmvStatus | 'todos')}
          >
            <SelectTrigger className="h-9 w-[160px] text-sm">
              <SelectValue placeholder="Status" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="todos">Todos os status</SelectItem>
              <SelectItem value="rascunho">Rascunho</SelectItem>
              <SelectItem value="aprovada">Aprovada</SelectItem>
              <SelectItem value="obsoleta">Obsoleta</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Content */}
        {isLoading ? (
          <div className="flex items-center justify-center py-20 text-muted-foreground text-sm">
            Carregando CMVs...
          </div>
        ) : filteredCmvs.length === 0 ? (
          <div className="flex flex-col items-center justify-center gap-3 py-20 text-center">
            <div className="rounded-2xl bg-[#57715B]/10 p-4">
              <Calculator className="h-10 w-10 text-[#57715B]" />
            </div>
            <p className="text-sm text-muted-foreground">
              {cmvList.length === 0
                ? 'Nenhum CMV cadastrado. Crie o primeiro!'
                : 'Nenhum CMV corresponde aos filtros.'}
            </p>
            {cmvList.length === 0 && (
              <Button
                size="sm"
                variant="outline"
                onClick={() => { setNewCmvNome(''); setSelectedFichaId(''); setIsNewDialogOpen(true); }}
              >
                <Plus className="mr-1.5 h-4 w-4" />
                Criar primeiro CMV
              </Button>
            )}
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-4 lg:gap-6">
            {filteredCmvs.map((cmv) => {
              const st = STATUS_CONFIG[cmv.status];
              const Icon = st.icon;
              const rendimento = cmv.ficha_rendimento_quantidade ?? 1;
              const custoFichaTotal = cmv.ficha_custo_calculado ?? 0;
              const unitarioFicha = rendimento > 0 ? custoFichaTotal / rendimento : 0;
              const custoTotal = cmv.custo_calculado ?? 0;
              const extras = Math.max(0, custoTotal - unitarioFicha);

              return (
                <div
                  key={cmv.id}
                  className="group relative rounded-2xl border border-white/30 dark:border-white/10 bg-white/60 dark:bg-zinc-900/40 backdrop-blur-xl shadow-sm hover:shadow-xl hover:-translate-y-1 p-5 transition-all duration-300 overflow-hidden"
                >
                  <div className="absolute inset-0 bg-gradient-to-br from-white/40 via-transparent to-black/5 pointer-events-none" />
                  <div className="relative z-10">
                    <div className="flex items-start justify-between gap-3 mb-3">
                      <div className="flex-1 min-w-0">
                        <p className="font-semibold text-base text-foreground truncate">{cmv.nome}</p>
                        {cmv.ficha_nome && (
                          <p className="text-xs text-muted-foreground truncate mt-0.5 flex items-center gap-1">
                            <Workflow className="h-3 w-3 shrink-0" />
                            {cmv.ficha_nome}
                          </p>
                        )}
                      </div>

                      <DropdownMenu>
                        <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-7 w-7 opacity-0 group-hover:opacity-100 transition-opacity"
                          >
                            <ChevronDown className="h-4 w-4" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem
                            onClick={() => navigate(`/financeiro/cmv/configurador?focus=${cmv.id}`)}
                          >
                            <Workflow className="mr-2 h-4 w-4 text-[#57715B]" />
                            Abrir no Construtor
                          </DropdownMenuItem>
                          {cmv.status !== 'aprovada' && (
                            <DropdownMenuItem
                              onClick={() => updateCmvStatus.mutate({ id: cmv.id, status: 'aprovada' })}
                            >
                              <CheckCircle2 className="mr-2 h-4 w-4 text-emerald-500" />
                              Aprovar
                            </DropdownMenuItem>
                          )}
                          {cmv.status !== 'obsoleta' && (
                            <DropdownMenuItem
                              onClick={() => updateCmvStatus.mutate({ id: cmv.id, status: 'obsoleta' })}
                            >
                              <Archive className="mr-2 h-4 w-4" />
                              Marcar obsoleta
                            </DropdownMenuItem>
                          )}
                          <DropdownMenuSeparator />
                          <DropdownMenuItem
                            className="text-destructive"
                            onClick={() => setDeleteId(cmv.id)}
                          >
                            <Trash2 className="mr-2 h-4 w-4" />
                            Excluir
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </div>

                    <span
                      className={cn(
                        'inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-[10px] uppercase tracking-wider font-bold',
                        st.className,
                      )}
                    >
                      <Icon className="h-3 w-3" />
                      {st.label}
                    </span>

                    <div className="mt-4 pt-3 border-t border-[#57715B]/10">
                      <div className="flex items-end justify-between">
                        <div>
                          <p className="text-[10px] text-muted-foreground uppercase tracking-wider mb-0.5">
                            Custo total
                          </p>
                          <p className="text-xl font-bold text-emerald-600 dark:text-emerald-400 tabular-nums">
                            {fmt(custoTotal)}
                          </p>
                        </div>
                        <div className="text-right space-y-0.5">
                          <p className="text-[10px] text-muted-foreground">
                            Produção:{' '}
                            <span className="font-semibold text-foreground tabular-nums">
                              {fmt(unitarioFicha)}
                            </span>
                          </p>
                          <p className="text-[10px] text-muted-foreground">
                            Extras:{' '}
                            <span className="font-semibold text-foreground tabular-nums">
                              {fmt(extras)}
                            </span>
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Dialog Novo CMV */}
      <Dialog open={isNewDialogOpen} onOpenChange={setIsNewDialogOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Novo CMV</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div className="space-y-2">
              <p className="text-sm font-medium">Ficha Técnica Base *</p>
              {availableFichas.length === 0 ? (
                <div className="rounded-lg border border-amber-200 dark:border-amber-800 bg-amber-50 dark:bg-amber-900/20 p-3 text-sm text-amber-700 dark:text-amber-400">
                  Todas as fichas aprovadas já possuem CMV cadastrado.
                </div>
              ) : (
                <Select value={selectedFichaId} onValueChange={handleFichaSelect}>
                  <SelectTrigger>
                    <SelectValue placeholder="Selecione a ficha aprovada..." />
                  </SelectTrigger>
                  <SelectContent>
                    {availableFichas.map((f) => (
                      <SelectItem key={f.id} value={String(f.id)}>
                        {f.nome} — {f.rendimento_quantidade} {f.rendimento_unidade}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
            </div>

            <div className="space-y-2">
              <p className="text-sm font-medium">Nome do CMV *</p>
              <Input
                placeholder="Ex: CMV — Bolo de Chocolate"
                value={newCmvNome}
                onChange={(e) => setNewCmvNome(e.target.value)}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsNewDialogOpen(false)}>
              Cancelar
            </Button>
            <Button
              className="bg-[#57715B] hover:bg-[#465b49] text-white"
              onClick={handleCreate}
              disabled={
                !selectedFichaId ||
                !newCmvNome.trim() ||
                availableFichas.length === 0 ||
                createCmv.isPending
              }
            >
              {createCmv.isPending ? 'Salvando...' : 'Salvar e Abrir Construtor'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Alert delete */}
      <AlertDialog open={!!deleteId} onOpenChange={(o) => !o && setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Excluir CMV?</AlertDialogTitle>
            <AlertDialogDescription>
              Esta ação é irreversível. Todos os itens de custo extras e posições do canvas serão removidos.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              className="bg-destructive text-destructive-foreground"
            >
              Excluir
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </MommaPageLayout>
  );
}

