677	
678	  // -------------------------------------------------------------------------
679	  // Build ReactFlow nodes/edges from hook data
680	  // -------------------------------------------------------------------------
681	  const buildGraph = useCallback(() => {
682	    if (!cmv) return;
683	
684	    const newNodes: Node[] = [];
685	    const newEdges: Edge[] = [];
686	
687	    const rootId = cmvNodeId(cmv.id);
688	
689	    // Root node
690	    newNodes.push({
691	      id: rootId,
692	      type: 'cmv',
693	      data: { nome: cmv.nome, custo: cmv.custo_calculado, status: cmv.status, kind: 'cmv' } as Record<string, unknown>,
694	      position: positions.get(rootId) ?? { x: 800, y: 300 },
695	    });
696	
697	    // Ficha base node
698	    if (fichaData) {
699	      const fId = fichaNodeId(fichaData.id);
700	      const rendQty = fichaData.rendimento_quantidade || 1;
701	      const custoUnitario = (fichaData.custo_calculado ?? 0) / rendQty;
702	
703	      newNodes.push({
704	        id: fId,
705	        type: 'ficha',
706	        data: {
707	          nome: fichaData.nome,
708	          custoUnitario,
709	          rendimento: `${fichaData.rendimento_quantidade} ${fichaData.rendimento_unidade}`,
710	          status: fichaData.status,
711	          kind: 'ficha',
712	        } as Record<string, unknown>,
713	        position: positions.get(fId) ?? { x: 400, y: 300 },
714	      });
715	
716	      newEdges.push({
717	        id: `e-${fId}-${rootId}`,
718	        source: fId,
719	        target: rootId,
720	        animated: true,
721	        style: { stroke: '#F59E0B', strokeWidth: 3 },
722	      });
723	    }
724	
725	    // Item nodes
726	    const addedInsumoIds = new Set<number>();
727	
728	    items.forEach((item, idx) => {
729	      const itemId = `item_${item.id}`;
730	      const label = item.insumo?.nome ?? item.observacao ?? `Item ${idx + 1}`;
731	
732	      newNodes.push({
733	        id: itemId,
734	        type: 'cmvItem',
735	        data: {
736	          tipo: item.tipo as TipoItem,
737	          quantidade: item.quantidade,
738	          unidade: item.unidade,
739	          custo: item.custo_calculado,
740	          label,
741	          kind: 'cmvItem',
742	          _rawItemId: item.id,
743	        } as Record<string, unknown>,
744	        position: positions.get(itemId) ?? { x: 400, y: 100 + idx * 160 },
745	      });
746	
747	      newEdges.push({
748	        id: `e-${itemId}-${rootId}`,
749	        source: itemId,
750	        target: rootId,
751	        style: { stroke: '#52525b', strokeWidth: 2 },
752	      });
753	
754	      // Insumo linked to item
755	      if (item.insumo_id && !addedInsumoIds.has(item.insumo_id)) {
756	        addedInsumoIds.add(item.insumo_id);
757	        const insId = insumoNodeId(item.insumo_id);
758	        const insData = insumos.find((i) => i.id === item.insumo_id);
759	
760	        newNodes.push({
761	          id: insId,
762	          type: 'insumo',
763	          data: {
764	            nome: insData?.nome ?? 'Insumo',
765	            preco: insData?.preco_custo ?? null,
766	            unidade: insData?.unidade_compra ?? 'un',
767	            kind: 'insumo',
768	          } as Record<string, unknown>,
769	          position: positions.get(insId) ?? { x: 100, y: 100 + idx * 160 },
770	        });
771	
772	        newEdges.push({
773	          id: `e-${insId}-${itemId}`,
774	          source: insId,
775	          target: itemId,
776	          style: { stroke: '#7c3aed', strokeWidth: 1.5 },
777	        });
778	      }
779	    });
780	
781	    // Apply dagre layout for nodes without saved positions
782	    const hasAllPositions = newNodes.every((n) => positions.has(n.id));
783	    if (!hasAllPositions && newNodes.length > 0) {
784	      const laid = layoutGraph(newNodes, newEdges, 'LR');
785	      setNodes(laid);
786	    } else {
787	      setNodes(newNodes);
788	    }
789	    setEdges(newEdges);
790	
791	    setTimeout(() => {
792	      fitView({ padding: 0.12, duration: 400 });
793	    }, 80);
794	  }, [cmv, fichaData, items, insumos, positions, fitView, setNodes, setEdges]);
795	
796	  useEffect(() => {
797	    if (!loading) {
798	      buildGraph();
799	    }
800	  }, [loading, buildGraph]);
801	
802	  // -------------------------------------------------------------------------
803	  // Node drag → save position
804	  // -------------------------------------------------------------------------
805	  const handleNodeDragStop: NodeDragHandler = useCallback(
806	    (_evt, node) => {
