823	      if (found) {
824	        setSelectedItemData(found);
825	        setEditQty(String(found.quantidade));
826	        setEditUnit(found.unidade);
827	        setEditPreco(found.preco_unitario_esboco !== null ? String(found.preco_unitario_esboco) : '');
828	        setEditObs(found.observacao ?? '');
829	      }
830	    },
831	    [items],
832	  );
833	
834	  // -------------------------------------------------------------------------
835	  // Auto-layout
836	  // -------------------------------------------------------------------------
837	  const handleAutoLayout = useCallback(() => {
838	    setNodes((prev) => {
