845	
846	  // -------------------------------------------------------------------------
847	  // Save item
848	  // -------------------------------------------------------------------------
849	  const handleSaveItem = useCallback(async () => {
850	    if (!selectedItemData) return;
851	    setIsSaving(true);
852	
853	    const updatePayload: Record<string, unknown> = {
854	      quantidade: parseFloat(editQty) || selectedItemData.quantidade,
855	      unidade: editUnit,
856	    };
857	    if (selectedItemData.tipo === 'outro') {
