859	      updatePayload.observacao = editObs.trim() || null;
860	    }
861	
862	    const { error } = await supabase
863	      .from('cmv_itens')
864	      .update(updatePayload)
865	      .eq('id', selectedItemData.id);
866	
867	    if (error) {
868	      toast.error(`Erro ao salvar: ${error.message}`);
869	    } else {
870	      toast.success('Item atualizado!');
871	      setSelectedItemData(null);
872	      await refetch();
873	      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
874	    }
875	    setIsSaving(false);
876	  }, [selectedItemData, editQty, editUnit, editPreco, editObs, refetch, queryClient]);
877	
878	  // -------------------------------------------------------------------------
879	  // Delete item
880	  // -------------------------------------------------------------------------
881	  const handleDeleteItem = useCallback(async () => {
882	    if (!selectedItemData) return;
883	    setIsDeleting(true);
884	    const { error } = await supabase
885	      .from('cmv_itens')
886	      .delete()
887	      .eq('id', selectedItemData.id);
888	
889	    if (error) {
890	      toast.error(`Erro ao excluir: ${error.message}`);
891	    } else {

892	      toast.success('Item removido!');
893	      setSelectedItemData(null);
894	      await refetch();
895	      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
896	    }
897	    setIsDeleting(false);
898	  }, [selectedItemData, refetch, queryClient]);
899	
900	  // -------------------------------------------------------------------------
901	  // Add item
902	  // -------------------------------------------------------------------------
903	  const handleAddItem = useCallback(async () => {
904	    if (!cmvId) return;
905	
906	    if (newTipo === 'embalagem' && !newInsumoId) {
907	      toast.error('Selecione um insumo para o item de embalagem.');
908	      return;
909	    }
910	    if (newTipo === 'outro' && newObs.trim() === '') {
911	      toast.error('Informe o nome do custo avulso no campo Observação.');
912	      return;
913	    }
914	
915	    setIsAddSaving(true);
916	
917	    const payload: Record<string, unknown> = {
918	      cmv_id: cmvId,
919	      tipo: newTipo,
920	      quantidade: parseFloat(newQty) || 1,
921	      unidade: newUnit,
922	      ordem: items.length,
923	    };
924	
925	    if (newTipo === 'embalagem') {
926	      payload.insumo_id = parseInt(newInsumoId, 10);
927	    } else {
928	      // outro: custo avulso
929	      payload.observacao = newObs.trim();
930	      payload.preco_unitario_esboco = newPreco !== '' ? parseFloat(newPreco) : null;
931	    }
932	
933	    const { error } = await supabase.from('cmv_itens').insert(payload);
934	
935	    if (error) {
936	      toast.error(`Erro ao criar item: ${error.message}`);
937	    } else {
938	      toast.success('Item adicionado!');
939	      setIsAddOpen(false);
940	      setNewTipo('embalagem');
941	      setNewInsumoId('');
942	      setNewQty('1');
943	      setNewUnit('un');
944	      setNewPreco('');
945	      setNewObs('');
946	      await refetch();
947	      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
948	    }
949	    setIsAddSaving(false);
950	  }, [cmvId, newTipo, newInsumoId, newQty, newUnit, newPreco, newObs, items.length, refetch, queryClient]);
951	
952	  // -------------------------------------------------------------------------
953	  // Empty/loading states
