const fmt = (v: number | null | undefined): string => {
  if (typeof v !== 'number') return 'R$ 0,00';
  return v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
};

type TipoItem = 'embalagem' | 'outro';

const TIPO_CONFIG: Record<TipoItem, { label: string; color: string; border: string; icon: React.ReactNode }> = {
  embalagem: {
    label: 'Embalagem',
    color: 'bg-blue-600/80',
    border: 'border-blue-400/40',
    icon: <Package size={12} />,
  },
  outro: {
    label: 'Custo avulso',
    color: 'bg-orange-700/60',
    border: 'border-dashed border-orange-400/60',
    icon: <DollarSign size={12} />,
  },
};

const STATUS_COLORS: Record<string, string> = {
  rascunho: 'bg-zinc-200/80 text-zinc-700 dark:bg-zinc-700 dark:text-zinc-300',
  aprovada: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-800/60 dark:text-emerald-300',
  obsoleta: 'bg-zinc-200/80 text-zinc-500 dark:bg-zinc-800 dark:text-zinc-500',
};

// ---------------------------------------------------------------------------
// CUSTOM NODE COMPONENTS
// ---------------------------------------------------------------------------

interface CmvRootNodeData extends Record<string, unknown> {
  nome: string;
  custo: number | null;
  status: string;
}

const CmvRootNode = memo(function CmvRootNode({ data }: NodeProps<CmvRootNodeData>) {
  return (
    <div className="relative px-5 py-4 rounded-2xl border border-[#57715B]/50 bg-[#57715B]/90 backdrop-blur-md text-white min-w-[260px] shadow-2xl shadow-[#57715B]/40">
      <div className="flex items-start justify-between mb-2 gap-2">
        <div className="flex items-center gap-1.5 opacity-80">
          <Calculator size={12} />
          <span className="text-[9px] font-bold uppercase tracking-wider">CMV Central</span>
        </div>
        <span className={`text-[9px] px-2 py-0.5 rounded-full font-bold uppercase tracking-wide ${STATUS_COLORS[data.status] ?? STATUS_COLORS.rascunho}`}>
          {data.status}
        </span>
      </div>
      <h3 className="text-base font-bold truncate leading-tight mb-2">{data.nome}</h3>
      <p className="text-2xl font-black tabular-nums">{fmt(data.custo)}</p>
      <Handle type="target" position={Position.Left} className="!w-3.5 !h-3.5 !bg-white/60 !border-2 !border-white/30" />
    </div>
  );
});

interface FichaBaseNodeData extends Record<string, unknown> {
  nome: string;
  custoUnitario: number;
  rendimento: string;
  status: string;
}

const FichaBaseNode = memo(function FichaBaseNode({ data }: NodeProps<FichaBaseNodeData>) {
  return (
    <div className="relative px-5 py-4 rounded-2xl border border-amber-500/40 bg-amber-700/80 backdrop-blur-md text-white min-w-[240px] shadow-xl shadow-amber-700/30">
      <div className="flex items-center gap-1.5 opacity-80 mb-2">
        <ChefHat size={12} />
        <span className="text-[9px] font-bold uppercase tracking-wider">Ficha Técnica Base</span>
      </div>
      <h3 className="text-base font-semibold truncate mb-1">{data.nome}</h3>
      <div className="flex items-end justify-between mt-2">
        <div>
          <p className="text-[9px] opacity-60 leading-none mb-0.5">Custo unitário</p>
          <p className="text-xl font-bold tabular-nums">{fmt(data.custoUnitario)}</p>
        </div>
        <span className="text-[10px] px-2 py-0.5 bg-white/20 rounded-full">{data.rendimento}</span>
      </div>
      <Handle type="source" position={Position.Right} className="!w-3 !h-3 !bg-amber-300 !border-2 !border-white" />
    </div>
  );
});

interface CmvItemNodeData extends Record<string, unknown> {
  tipo: TipoItem;
  quantidade: number;
  unidade: string;
  custo: number | null;
  label: string;
}

const CmvItemNode = memo(function CmvItemNode({ data, selected }: NodeProps<CmvItemNodeData>) {
  const cfg = TIPO_CONFIG[data.tipo as TipoItem] ?? TIPO_CONFIG.outro;
  return (
    <div className={`relative px-4 py-3 rounded-xl border backdrop-blur-md text-zinc-100 min-w-[200px] shadow-lg transition-all duration-150 ${cfg.color} ${cfg.border} ${selected ? 'ring-2 ring-white/40 scale-[1.02]' : 'hover:shadow-xl hover:-translate-y-0.5'}`}>
      <div className="flex items-center gap-1.5 mb-2">
        <span className="opacity-80">{cfg.icon}</span>
        <span className="text-[9px] font-bold uppercase tracking-wider opacity-80">{cfg.label}</span>
      </div>
      <h4 className="text-sm font-semibold truncate mb-1.5">{data.label}</h4>
      <div className="flex items-end justify-between">
        <span className="text-[11px] text-white/70">{data.quantidade} {data.unidade}</span>
        <span className="text-base font-bold tabular-nums">{fmt(data.custo)}</span>
      </div>
      <Handle type="target" position={Position.Left} className="!w-2.5 !h-2.5 !bg-white/40 !border-2 !border-white/20" />
      <Handle type="source" position={Position.Right} className="!w-2.5 !h-2.5 !bg-white/60 !border-2 !border-white/30" />
    </div>
  );
});

interface InsumoNodeData extends Record<string, unknown> {
  nome: string;
  preco: number | null;
  unidade: string;
}

const InsumoNode = memo(function InsumoNode({ data }: NodeProps<InsumoNodeData>) {
  return (
    <div className="px-3 py-2 rounded-lg border border-violet-400/30 bg-violet-700/70 backdrop-blur-sm text-white min-w-[180px] shadow-md">
      <div className="flex items-center gap-1 mb-1 opacity-70">
        <Wheat size={10} />
        <span className="text-[9px] font-bold uppercase">Insumo</span>
      </div>
      <h4 className="text-xs font-semibold truncate">{data.nome}</h4>
      <p className="text-sm font-bold tabular-nums">
        {fmt(data.preco)} <span className="text-[9px] font-normal opacity-60">/{data.unidade}</span>
      </p>
      <Handle type="source" position={Position.Right} className="!w-2 !h-2 !bg-violet-300 !border-2 !border-white" />
    </div>
  );
});

interface NFNodeData extends Record<string, unknown> {
  fornecedor: string;
  numero: string | null;
  valor: number | null;
}

const NFNode = memo(function NFNode({ data }: NodeProps<NFNodeData>) {
  return (
    <div className="px-3 py-2 rounded-lg border border-cyan-400/30 bg-cyan-700/70 backdrop-blur-sm text-white min-w-[160px] shadow-md">
      <div className="flex items-center gap-1 mb-1 opacity-70">
        <Receipt size={10} />
        <span className="text-[9px] font-bold uppercase">Nota Fiscal</span>
      </div>
      <h4 className="text-[11px] font-semibold truncate">{data.fornecedor || 'Fornecedor'}</h4>
      {data.numero && <p className="text-[9px] opacity-60">#{data.numero}</p>}
      <p className="text-xs font-bold tabular-nums">{fmt(data.valor)}</p>
      <Handle type="source" position={Position.Right} className="!w-2 !h-2 !bg-cyan-300 !border-2 !border-white" />
    </div>
  );
});

const nodeTypes: NodeTypes = {
  cmv: CmvRootNode,
  ficha: FichaBaseNode,
  cmvItem: CmvItemNode,
  insumo: InsumoNode,
  nf: NFNode,
};

// ---------------------------------------------------------------------------
// INNER COMPONENT (usa useReactFlow())
// ---------------------------------------------------------------------------

function CmvConfiguratorInner() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const cmvIdParam = searchParams.get('focus');
  const cmvId = cmvIdParam !== null && cmvIdParam !== '' ? parseInt(cmvIdParam, 10) : null;

  const {
    loading,
    cmv,
    fichaData,
    items,
    insumos,
    positions,
    savePosition,
    refetch,
  } = useCmvGraph(cmvId);

  const { fitView } = useReactFlow();
  const queryClient = useQueryClient();
  const [nodes, setNodes, onNodesChange] = useNodesState([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState([]);

  // Detail panel state
  const [selectedItemData, setSelectedItemData] = useState<RawCmvItem | null>(null);
  const [editQty, setEditQty] = useState('');
  const [editUnit, setEditUnit] = useState('');
  const [editPreco, setEditPreco] = useState('');
  const [editObs, setEditObs] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  // Add item dialog state
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [newTipo, setNewTipo] = useState<TipoItem>('embalagem');
  const [newInsumoId, setNewInsumoId] = useState<string>('');
  const [newQty, setNewQty] = useState('1');
  const [newUnit, setNewUnit] = useState('un');
  const [newPreco, setNewPreco] = useState('');
  const [newObs, setNewObs] = useState('');
  const [isAddSaving, setIsAddSaving] = useState(false);

  // -------------------------------------------------------------------------
  // Build ReactFlow nodes/edges from hook data
  // -------------------------------------------------------------------------
  const buildGraph = useCallback(() => {
    if (!cmv) return;

    const newNodes: Node[] = [];
    const newEdges: Edge[] = [];

    const rootId = cmvNodeId(cmv.id);

    // Root node
    newNodes.push({
      id: rootId,
      type: 'cmv',
      data: { nome: cmv.nome, custo: cmv.custo_calculado, status: cmv.status, kind: 'cmv' } as Record<string, unknown>,
      position: positions.get(rootId) ?? { x: 800, y: 300 },
    });

    // Ficha base node
    if (fichaData) {
      const fId = fichaNodeId(fichaData.id);
      const rendQty = fichaData.rendimento_quantidade || 1;
      const custoUnitario = (fichaData.custo_calculado ?? 0) / rendQty;

      newNodes.push({
        id: fId,
        type: 'ficha',
        data: {
          nome: fichaData.nome,
          custoUnitario,
          rendimento: `${fichaData.rendimento_quantidade} ${fichaData.rendimento_unidade}`,
          status: fichaData.status,
          kind: 'ficha',
        } as Record<string, unknown>,
        position: positions.get(fId) ?? { x: 400, y: 300 },
      });

      newEdges.push({
        id: `e-${fId}-${rootId}`,
        source: fId,
        target: rootId,
        animated: true,
        style: { stroke: '#F59E0B', strokeWidth: 3 },
      });
    }

    // Item nodes
    const addedInsumoIds = new Set<number>();

    items.forEach((item, idx) => {
      const itemId = `item_${item.id}`;
      const label = item.insumo?.nome ?? item.observacao ?? `Item ${idx + 1}`;

      newNodes.push({
        id: itemId,
        type: 'cmvItem',
        data: {
          tipo: item.tipo as TipoItem,
          quantidade: item.quantidade,
          unidade: item.unidade,
          custo: item.custo_calculado,
          label,
          kind: 'cmvItem',
          _rawItemId: item.id,
        } as Record<string, unknown>,
        position: positions.get(itemId) ?? { x: 400, y: 100 + idx * 160 },
      });

      newEdges.push({
        id: `e-${itemId}-${rootId}`,
        source: itemId,
        target: rootId,
        style: { stroke: '#52525b', strokeWidth: 2 },
      });

      // Insumo linked to item
      if (item.insumo_id && !addedInsumoIds.has(item.insumo_id)) {
        addedInsumoIds.add(item.insumo_id);
        const insId = insumoNodeId(item.insumo_id);
        const insData = insumos.find((i) => i.id === item.insumo_id);

        newNodes.push({
          id: insId,
          type: 'insumo',
          data: {
            nome: insData?.nome ?? 'Insumo',
            preco: insData?.preco_custo ?? null,
            unidade: insData?.unidade_compra ?? 'un',
            kind: 'insumo',
          } as Record<string, unknown>,
          position: positions.get(insId) ?? { x: 100, y: 100 + idx * 160 },
        });

        newEdges.push({
          id: `e-${insId}-${itemId}`,
          source: insId,
          target: itemId,
          style: { stroke: '#7c3aed', strokeWidth: 1.5 },
        });
      }
    });

    // Apply dagre layout for nodes without saved positions
    const hasAllPositions = newNodes.every((n) => positions.has(n.id));
    if (!hasAllPositions && newNodes.length > 0) {
      const laid = layoutGraph(newNodes, newEdges, 'LR');
      setNodes(laid);
    } else {
      setNodes(newNodes);
    }
    setEdges(newEdges);

    setTimeout(() => {
      fitView({ padding: 0.12, duration: 400 });
    }, 80);
  }, [cmv, fichaData, items, insumos, positions, fitView, setNodes, setEdges]);

  useEffect(() => {
    if (!loading) {
      buildGraph();
    }
  }, [loading, buildGraph]);

  // -------------------------------------------------------------------------
  // Node drag → save position
  // -------------------------------------------------------------------------
  const handleNodeDragStop: NodeDragHandler = useCallback(
    (_evt, node) => {
      savePosition(node.id, node.position.x, node.position.y);
    },
    [savePosition],
  );

  // -------------------------------------------------------------------------
  // Node click → open detail panel
  // -------------------------------------------------------------------------
  const handleNodeClick = useCallback(
    (_evt: React.MouseEvent, node: Node) => {
      const rawId = (node.data as Record<string, unknown>)._rawItemId;
      if (typeof rawId !== 'number') {
        setSelectedItemData(null);
        return;
      }
      const found = items.find((it) => it.id === rawId);
      if (found) {
        setSelectedItemData(found);
        setEditQty(String(found.quantidade));
        setEditUnit(found.unidade);
        setEditPreco(found.preco_unitario_esboco !== null ? String(found.preco_unitario_esboco) : '');
        setEditObs(found.observacao ?? '');
      }
    },
    [items],
  );

  // -------------------------------------------------------------------------
  // Auto-layout
  // -------------------------------------------------------------------------
  const handleAutoLayout = useCallback(() => {
    setNodes((prev) => {
      const laid = layoutGraph(prev, edges, 'LR');
      laid.forEach((n) => savePosition(n.id, n.position.x, n.position.y));
      return laid;
    });
    setTimeout(() => fitView({ padding: 0.12, duration: 400 }), 80);
  }, [edges, fitView, savePosition, setNodes]);

  // -------------------------------------------------------------------------
  // Save item
  // -------------------------------------------------------------------------
  const handleSaveItem = useCallback(async () => {
    if (!selectedItemData) return;
    setIsSaving(true);

    const updatePayload: Record<string, unknown> = {
      quantidade: parseFloat(editQty) || selectedItemData.quantidade,
      unidade: editUnit,
    };
    if (selectedItemData.tipo === 'outro') {
      updatePayload.preco_unitario_esboco = editPreco !== '' ? parseFloat(editPreco) : null;
      updatePayload.observacao = editObs.trim() || null;
    }

    const { error } = await supabase
      .from('cmv_itens')
      .update(updatePayload)
      .eq('id', selectedItemData.id);

    if (error) {
      toast.error(`Erro ao salvar: ${error.message}`);
    } else {
      toast.success('Item atualizado!');
      setSelectedItemData(null);
      await refetch();
      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
    }
    setIsSaving(false);
  }, [selectedItemData, editQty, editUnit, editPreco, editObs, refetch, queryClient]);

  // -------------------------------------------------------------------------
  // Delete item
  // -------------------------------------------------------------------------
  const handleDeleteItem = useCallback(async () => {
    if (!selectedItemData) return;
    setIsDeleting(true);
    const { error } = await supabase
      .from('cmv_itens')
      .delete()
      .eq('id', selectedItemData.id);

    if (error) {
      toast.error(`Erro ao excluir: ${error.message}`);
    } else {
      toast.success('Item removido!');
      setSelectedItemData(null);
      await refetch();
      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
    }
    setIsDeleting(false);
  }, [selectedItemData, refetch, queryClient]);

  // -------------------------------------------------------------------------
  // Add item
  // -------------------------------------------------------------------------
  const handleAddItem = useCallback(async () => {
    if (!cmvId) return;

    if (newTipo === 'embalagem' && !newInsumoId) {
      toast.error('Selecione um insumo para o item de embalagem.');
      return;
    }
    if (newTipo === 'outro' && newObs.trim() === '') {
      toast.error('Informe o nome do custo avulso no campo Observação.');
      return;
    }

    setIsAddSaving(true);

    const payload: Record<string, unknown> = {
      cmv_id: cmvId,
      tipo: newTipo,
      quantidade: parseFloat(newQty) || 1,
      unidade: newUnit,
      ordem: items.length,
    };

    if (newTipo === 'embalagem') {
      payload.insumo_id = parseInt(newInsumoId, 10);
    } else {
      // outro: custo avulso
      payload.observacao = newObs.trim();
      payload.preco_unitario_esboco = newPreco !== '' ? parseFloat(newPreco) : null;
    }

    const { error } = await supabase.from('cmv_itens').insert(payload);

    if (error) {
      toast.error(`Erro ao criar item: ${error.message}`);
    } else {
      toast.success('Item adicionado!');
      setIsAddOpen(false);
      setNewTipo('embalagem');
      setNewInsumoId('');
      setNewQty('1');
      setNewUnit('un');
      setNewPreco('');
      setNewObs('');
      await refetch();
      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
    }
    setIsAddSaving(false);
  }, [cmvId, newTipo, newInsumoId, newQty, newUnit, newPreco, newObs, items.length, refetch, queryClient]);

  // -------------------------------------------------------------------------
  // Empty/loading states
  // -------------------------------------------------------------------------
  if (!cmvId) {
    return (
      <div className="h-[100dvh] bg-slate-50 dark:bg-slate-950 flex flex-col items-center justify-center text-muted-foreground">
        <Calculator className="h-12 w-12 mb-4 text-[#57715B]" />
        <p className="text-sm mb-4">Nenhum CMV selecionado</p>
        <Button variant="outline" onClick={() => navigate('/financeiro/cmv')}>
          <ArrowLeft className="mr-2 h-4 w-4" />
          Voltar ao CMV
        </Button>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="h-[100dvh] bg-slate-50 dark:bg-slate-950 flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-[#57715B]" />
      </div>
    );
  }

  if (!cmv) {
    return (
      <div className="h-[100dvh] bg-slate-50 dark:bg-slate-950 flex flex-col items-center justify-center text-muted-foreground">
        <p className="text-sm mb-4">CMV não encontrado.</p>
        <Button variant="outline" onClick={() => navigate('/financeiro/cmv')}>
          <ArrowLeft className="mr-2 h-4 w-4" />
          Voltar
        </Button>
      </div>
    );
  }

  // -------------------------------------------------------------------------
  // Render
  // -------------------------------------------------------------------------
  return (
    <div className="fixed inset-0 bg-slate-50 dark:bg-slate-950 overflow-hidden">
      {/* Ambient blobs coloridos */}
      <div className="fixed top-[-10%] left-[-10%] w-[500px] h-[500px] bg-amber-500/10 blur-3xl rounded-full pointer-events-none" />
      <div className="fixed top-[20%] right-[-5%] w-[400px] h-[400px] bg-emerald-500/10 blur-3xl rounded-full pointer-events-none" />
      <div className="fixed bottom-[-10%] left-[20%] w-[600px] h-[600px] bg-indigo-500/10 blur-3xl rounded-full pointer-events-none" />

      <ReactFlow
        nodes={nodes}
        edges={edges}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        nodeTypes={nodeTypes}
        onNodeDragStop={handleNodeDragStop}
        onNodeClick={handleNodeClick}
        fitView
        proOptions={{ hideAttribution: true }}
        minZoom={0.2}
        maxZoom={2}
      >
        <Background variant={BackgroundVariant.Dots} color="#cbd5e1" gap={20} />
        <MiniMap
          className="!bg-white/90 !backdrop-blur !rounded-lg !shadow-md"
          nodeColor={() => '#57715B'}
          maskColor="rgba(0,0,0,0.6)"
        />

        {/* Toolbar topo esquerdo */}
        <Panel position="top-left">
          <div className="flex items-center gap-2 bg-white/90 dark:bg-slate-900/85 border border-border backdrop-blur-md rounded-xl px-3 py-2 shadow-xl">
            <Button
              variant="ghost"
              size="icon"
              aria-label="Voltar para lista de CMVs"
              className="h-7 w-7 text-muted-foreground hover:text-foreground"
              onClick={() => navigate('/financeiro/cmv')}
            >
              <ArrowLeft size={16} />
            </Button>
            <div className="w-px h-5 bg-border" />
            <div className="flex items-center gap-2">
              <Calculator size={14} className="text-[#57715B]" />
              <span className="text-sm font-semibold text-foreground truncate max-w-[200px]">
                {cmv.nome}
              </span>
              <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold uppercase tracking-wide ${STATUS_COLORS[cmv.status] ?? STATUS_COLORS.rascunho}`}>
                {cmv.status}
              </span>
            </div>
            <div className="w-px h-5 bg-border" />
            <Button
              variant="ghost"
              size="sm"
              className="h-7 text-xs text-muted-foreground hover:text-foreground gap-1.5"
              onClick={handleAutoLayout}
            >
              <LayoutTemplate size={13} />
              <span className="hidden sm:inline">Auto-layout</span>
            </Button>
            <Button
              size="sm"
              className="h-7 text-xs bg-[#57715B] hover:bg-[#465b49] text-white gap-1.5"
              onClick={() => setIsAddOpen(true)}
            >
              <Plus size={13} />
              <span className="hidden sm:inline">Adicionar</span>
            </Button>
          </div>
        </Panel>

        {/* Legenda top-right */}
        <Panel position="top-right">
          <div className="flex flex-col gap-1.5 bg-white/90 dark:bg-slate-900/85 border border-border backdrop-blur-md rounded-xl p-3 shadow-lg text-[10px] text-muted-foreground">
            {(Object.entries(TIPO_CONFIG) as [TipoItem, typeof TIPO_CONFIG[TipoItem]][]).map(([tipo, cfg]) => (
              <div key={tipo} className="flex items-center gap-1.5">
                <span className="opacity-80">{cfg.icon}</span>
                <span>{cfg.label}</span>
              </div>
            ))}
          </div>
        </Panel>
      </ReactFlow>

      {/* Detail Panel (Sheet) */}
      <Sheet open={!!selectedItemData} onOpenChange={(o) => !o && setSelectedItemData(null)}>
        <SheetContent side="right" className="bg-white dark:bg-slate-900 border-border w-full sm:max-w-[380px]">
          <SheetHeader className="mb-4">
            <SheetTitle>Editar Item</SheetTitle>
          </SheetHeader>

          {selectedItemData && (
            <div className="space-y-4">
              {/* Tipo (read-only) */}
              <div>
                <Label className="text-xs text-muted-foreground">Tipo</Label>
                <p className="text-sm font-semibold mt-1">
                  {TIPO_CONFIG[selectedItemData.tipo as TipoItem]?.label ?? selectedItemData.tipo}
                </p>
              </div>

              {/* Insumo vinculado (embalagem) — somente leitura no edit */}
              {selectedItemData.tipo === 'embalagem' && selectedItemData.insumo && (
                <div>
                  <Label className="text-xs text-muted-foreground">Insumo</Label>
                  <p className="text-sm font-semibold mt-1 text-blue-600 dark:text-blue-300">{selectedItemData.insumo.nome}</p>
                </div>
              )}

              {/* Nome do custo avulso (outro) */}
              {selectedItemData.tipo === 'outro' && (
                <div>
                  <Label className="text-xs text-muted-foreground">Nome do custo</Label>
                  <Input
                    className="mt-1"
                    placeholder="Ex: Frete, Overhead, etc."
                    value={editObs}
                    onChange={(e) => setEditObs(e.target.value)}
                  />
                </div>
              )}

              {/* Quantidade + Unidade */}
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <Label className="text-xs text-muted-foreground">Quantidade</Label>
                  <Input
                    type="number"
                    className="mt-1"
                    value={editQty}
                    onChange={(e) => setEditQty(e.target.value)}
                  />
                </div>
                <div>
                  <Label className="text-xs text-muted-foreground">Unidade</Label>
                  <Input
                    className="mt-1"
                    value={editUnit}
                    onChange={(e) => setEditUnit(e.target.value)}
                  />
                </div>
              </div>

              {/* Preço unitário: somente para custo avulso */}
              {selectedItemData.tipo === 'outro' && (
                <div>
                  <Label className="text-xs text-muted-foreground">Preço unitário (esboço)</Label>
                  <Input
                    type="number"
                    step="0.01"
                    className="mt-1"
                    placeholder="0,00"
                    value={editPreco}
                    onChange={(e) => setEditPreco(e.target.value)}
                  />
                </div>
              )}

              {selectedItemData.custo_calculado !== null && (
                <div className="pt-2 border-t border-border">
                  <p className="text-xs text-muted-foreground">Custo calculado</p>
                  <p className="text-xl font-bold text-emerald-600 dark:text-emerald-400 tabular-nums">
                    {fmt(selectedItemData.custo_calculado)}
                  </p>
                </div>
              )}
            </div>
          )}

          <SheetFooter className="mt-6 flex gap-2">
            <Button
              variant="destructive"
              size="sm"
              className="flex-1"
              onClick={handleDeleteItem}
              disabled={isDeleting || isSaving}
            >
              {isDeleting ? <Loader2 size={14} className="animate-spin mr-1" /> : <Trash2 size={14} className="mr-1" />}
              Excluir
            </Button>
            <Button
              size="sm"
              className="flex-1 bg-[#57715B] hover:bg-[#465b49] text-white"
              onClick={handleSaveItem}
              disabled={isSaving || isDeleting}
            >
              {isSaving ? <Loader2 size={14} className="animate-spin mr-1" /> : <Save size={14} className="mr-1" />}
              Salvar
            </Button>
          </SheetFooter>
        </SheetContent>
      </Sheet>

      {/* Add Item Dialog */}
      <Dialog open={isAddOpen} onOpenChange={setIsAddOpen}>
        <DialogContent className="bg-white dark:bg-slate-900 border-border">
          <DialogHeader>
            <DialogTitle>Adicionar Item de Custo</DialogTitle>
          </DialogHeader>

          <div className="space-y-4 py-2">
            {/* Tipo de custo */}
            <div>
              <Label className="text-xs text-muted-foreground">Tipo de custo</Label>
              <Select
                value={newTipo}
                onValueChange={(v) => {
                  setNewTipo(v as TipoItem);
                  setNewInsumoId('');
                  setNewObs('');
                  setNewPreco('');
                  setNewUnit('un');
                  setNewQty('1');
                }}
              >
                <SelectTrigger className="mt-1">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {(Object.entries(TIPO_CONFIG) as [TipoItem, typeof TIPO_CONFIG[TipoItem]][]).map(([tipo, cfg]) => (
                    <SelectItem key={tipo} value={tipo}>
                      <div className="flex items-center gap-1.5">
                        {cfg.icon}
                        {cfg.label}
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Embalagem: selecionar insumo */}
            {newTipo === 'embalagem' && (
              <div>
                <Label className="text-xs text-muted-foreground">
                  Insumo <span className="text-orange-500 dark:text-orange-400">*</span>
                </Label>
                <Select value={newInsumoId} onValueChange={setNewInsumoId}>
                  <SelectTrigger className="mt-1">
                    <SelectValue placeholder="Selecione o insumo..." />
                  </SelectTrigger>
                  <SelectContent className="max-h-60 overflow-y-auto">
                    {insumos
                      .slice()
                      .sort((a, b) => {
                        const aEmb = (a.categoria ?? '').toLowerCase().includes('embalagem') ? 0 : 1;
                        const bEmb = (b.categoria ?? '').toLowerCase().includes('embalagem') ? 0 : 1;
                        if (aEmb !== bEmb) return aEmb - bEmb;
                        return a.nome.localeCompare(b.nome, 'pt-BR');
                      })
                      .map((ins) => {
                        const isEmb = (ins.categoria ?? '').toLowerCase().includes('embalagem');
                        return (
                          <SelectItem key={ins.id} value={String(ins.id)}>
                            <div className="flex items-center gap-1.5 w-full">
                              {isEmb && <Package size={10} className="text-blue-600 dark:text-blue-400 shrink-0" />}
                              <span className={isEmb ? 'font-medium' : 'opacity-80'}>{ins.nome}</span>
                              {ins.preco_custo !== null && (
                                <span className="text-[10px] text-muted-foreground ml-auto">
                                  {ins.preco_custo.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}/{ins.unidade_compra ?? 'un'}
                                </span>
                              )}
                            </div>
                          </SelectItem>
                        );
                      })}
                  </SelectContent>
                </Select>
              </div>
            )}

            {/* Custo avulso (outro): nome livre */}
            {newTipo === 'outro' && (
              <div>
                <Label className="text-xs text-muted-foreground">
                  Nome do custo <span className="text-orange-500 dark:text-orange-400">*</span>
                </Label>
                <Input
                  className="mt-1"
                  placeholder="Ex: Frete, Overhead, Gás, etc."
                  value={newObs}
                  onChange={(e) => setNewObs(e.target.value)}
                />
              </div>
            )}

            {/* Quantidade + Unidade */}
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label className="text-xs text-muted-foreground">Quantidade</Label>
                <Input
                  type="number"
                  className="mt-1"
                  value={newQty}
                  onChange={(e) => setNewQty(e.target.value)}
                />
              </div>
              <div>
                <Label className="text-xs text-muted-foreground">Unidade</Label>
                <Input
                  className="mt-1"
                  placeholder="un, kg, cx..."
                  value={newUnit}
                  onChange={(e) => setNewUnit(e.target.value)}
                />
              </div>
            </div>

            {/* Preço unitário: só para custo avulso */}
            {newTipo === 'outro' && (
              <div>
                <Label className="text-xs text-muted-foreground">Preço unitário (esboço)</Label>
                <Input
                  type="number"
                  step="0.01"
                  className="mt-1"
                  placeholder="0,00"
                  value={newPreco}
                  onChange={(e) => setNewPreco(e.target.value)}
                />
              </div>
            )}
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setIsAddOpen(false)}>
              Cancelar
            </Button>
            <Button
              className="bg-[#57715B] hover:bg-[#465b49] text-white"
              onClick={handleAddItem}
              disabled={
                isAddSaving ||
                (newTipo === 'embalagem' && !newInsumoId) ||
                (newTipo === 'outro' && !newObs.trim())
              }
            >
              {isAddSaving ? <Loader2 size={14} className="animate-spin mr-1" /> : <Plus size={14} className="mr-1" />}
              Adicionar
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// ---------------------------------------------------------------------------
// PUBLIC EXPORT — ReactFlowProvider wrapper
// ---------------------------------------------------------------------------

export default function CmvConfiguratorPage() {
  return (
    <ReactFlowProvider>
      <CmvConfiguratorInner />
    </ReactFlowProvider>
  );
}

